class Solution {
    public int minSubArrayLen(int target, int[] nums) {
        int left = 0, total = 0, best = nums.length + 1;
        for (int right = 0; right < nums.length; right++) {
            total += nums[right];
            while (total >= target) {
                best = Math.min(best, right - left + 1);
                total -= nums[left];
                left++;
            }
        }
        return best > nums.length ? 0 : best;
    }
}

